syarah:
[
  {
    "name": "Umdat al-Fiqh",
    "author": "Ibn Qudamah al-Maqdisi",
    "desc": "Kitab matan fiqih mazhab Hanbali dasar yang memuat satu pendapat terkuat."
  },
  {
    "name": "Al-Muqni'",
    "author": "Ibn Qudamah al-Maqdisi",
    "desc": "Kitab fiqih tingkat menengah mazhab Hanbali yang menyebutkan beberapa riwayat."
  },
  {
    "name": "Al-Syarh al-Kabir",
    "author": "Shams al-Din Ibn Qudamah al-Maqdisi",
    "desc": "Syarah luas atas kitab Al-Muqni' dalam fiqih perbandingan mazhab Hanbali."
  },
  {
    "name": "Al-Uddah Syarh al-Muqni'",
    "author": "Baha' al-Din al-Maqdisi",
    "desc": "Penjelasan rinci dan sistematis atas kitab fiqih Al-Muqni' karya Ibn Qudamah."
  },
  {
    "name": "Al-Iqna' li-Talib al-Intifa'",
    "author": "Musa bin Ahmad al-Hajjawi",
    "desc": "Kitab induk hukum fiqih mazhab Hanbali yang menjadi pegangan para qadi."
  },
  {
    "name": "Muntaha al-Iradat",
    "author": "Ibn al-Najjar al-Futuhi",
    "desc": "Rujukan utama fatwa dan hukum paling muktamad dalam mazhab Hanbali."
  },
  {
    "name": "Daqaiq Uli al-Nuha",
    "author": "Mansur bin Yunus al-Buhuti",
    "desc": "Syarah terperinci atas kitab fiqih Muntaha al-Iradat karya Ibn al-Najjar."
  },
  {
    "name": "Matalib Uli al-Nuha",
    "author": "Mustafa al-Ruhaybani",
    "desc": "Syarah kitab Ghayat al-Muntaha dalam fiqih Hanbali tingkat lanjut."
  },
  {
    "name": "Bidayat al-Abed",
    "author": "Abdul Qadir bin Umar al-Taghlabi",
    "desc": "Matan fiqih ibadah ringkas dalam mazhab Hanbali untuk pemula."
  },
  {
    "name": "Al-Raudh al-Nadi",
    "author": "Mansur bin Yunus al-Buhuti",
    "desc": "Syarah matan fiqih Umdat al-Talib karya al-Karmis dalam mazhab Hanbali."
  },
  {
    "name": "Bahr al-Madhhab",
    "author": "Abu al-Mahasin al-Ruyani",
    "desc": "Ensiklopedi besar fiqih mazhab Syafi'i yang memuat perbedaan pendapat."
  },
  {
    "name": "Al-Tahdhib fi Fiqh al-Imam al-Syafi'i",
    "author": "Abu Muhammad al-Baghawi",
    "desc": "Kitab fiqih Syafi'i klasik yang komprehensif karya penyusun Masabih as-Sunnah."
  },
  {
    "name": "Al-Tatimmah",
    "author": "Abu al-Futuh al-Mutawalli",
    "desc": "Kitab penyempurna hukum fiqih Syafi'i memperkaya kajian metodis klasik."
  },
  {
    "name": "Mukhtasar al-Buwaiti",
    "author": "Abu Ya'qub al-Buwaiti",
    "desc": "Ringkasan fiqih Syafi'i paling awal karya murid utama Imam al-Syafi'i."
  },
  {
    "name": "Al-Risalah al-Jami'ah",
    "author": "Ahmad bin Zain al-Habshi",
    "desc": "Kitab ringkas dasar fiqih ibadah dan tasawuf dalam mazhab Syafi'i."
  },
  {
    "name": "Safinat al-Salat",
    "author": "Abdullah bin Umar al-Hadrami",
    "desc": "Kitab panduan praktis khusus tata cara salat dan bersuci mazhab Syafi'i."
  },
  {
    "name": "Mawhibah Dhi al-Fadl",
    "author": "Muhammad Mahfuz al-Tarmasi",
    "desc": "Hasyiyah mendalam atas Syarh al-Muqaddimah al-Hadramiyyah fiqih Syafi'i."
  },
  {
    "name": "An-Nafahat al-Jaliliyyah",
    "author": "Ahmad bin Umar al-Shatiri",
    "desc": "Syarah atas Safinatun Najah memuat penjelasan hukum ibadah Syafi'iyah."
  },
  {
    "name": "Bulugh al-Muna",
    "author": "Muhammad bin Ali al-Ba'atiyyah",
    "desc": "Syarah kontekstual dan luas atas matan fiqih Safinatun Najah."
  },
  {
    "name": "Al-Khilafiyyat",
    "author": "Abu Bakr al-Bayhaqi",
    "desc": "Studi dalil perbandingan fiqih Syafi'i dengan mazhab lain secara dalil hadis."
  },
  {
    "name": "Al-Uddah fi Furu' al-Syafi'iyyah",
    "author": "Al-Qadi Husain al-Marwazi",
    "desc": "Rujukan fiqih Syafi'i klasik aliran Khurasan yang memuat kaidah cabang."
  },
  {
    "name": "Al-Ibanah 'an Furu' al-Diyanah",
    "author": "Abu al-Qasim al-Furan al-Mutawalli",
    "desc": "Kitab fiqih Syafi'i klasik berpengaruh dalam mentarjih qaul ulama."
  },
  {
    "name": "Al-Kharashi 'ala Mukhtasar Khalil",
    "author": "Muhammad al-Kharashi",
    "desc": "Syarah populer atas Mukhtasar Khalil yang menjadi pegangan fiqih Maliki."
  },
  {
    "name": "Syarh al-Zarqani 'ala Mukhtasar Khalil",
    "author": "Abd al-Baqi al-Zarqani",
    "desc": "Penjelasan sistematis dan aplikatif atas kitab standar fiqih Maliki."
  },
  {
    "name": "Al-Bayan wa al-Tahsil",
    "author": "Ibn Rushd al-Jadd",
    "desc": "Ensiklopedi fiqih Maliki yang menjelaskan masalah-masalah dari al-Utbiyyah."
  },
  {
    "name": "At-Tafri'",
    "author": "Ibn al-Jallab al-Basri",
    "desc": "Kitab induk fiqih Maliki klasik berisi cabangan hukum secara ringkas."
  },
  {
    "name": "Hashiyah al-Sawi 'ala al-Syarh al-Saghir",
    "author": "Ahmad al-Sawi",
    "desc": "Catatan pinggir kritis atas Syarh al-Saghir karya al-Dardir mazhab Maliki."
  },
  {
    "name": "Al-Jawahir al-Zakiyyah",
    "author": "Ahmad bin Turki al-Maliki",
    "desc": "Syarah matan al-Izyawiyyah fiqih Maliki untuk tingkat pemula."
  },
  {
    "name": "Tuhfat al-Hukkam",
    "author": "Ibn Asim al-Gharnati",
    "desc": "Matan berbentuk nazam tentang fiqih peradilan dan muamalah mazhab Maliki."
  },
  {
    "name": "Tabsirat al-Hukkam",
    "author": "Ibn Farhun al-Maliki",
    "desc": "Kitab fiqih peradilan, prosedur hukum, dan kepemimpinan mazhab Maliki."
  },
  {
    "name": "Al-Inayah Syarh al-Hidayah",
    "author": "Akmal al-Din al-Babarti",
    "desc": "Syarah ilmiah mendalam atas kitab Al-Hidayah dalam fiqih Hanafi."
  },
  {
    "name": "Majma' al-Anhur",
    "author": "Damad Efendi (Sheikh Zadeh)",
    "desc": "Syarah rinci atas Multaqa al-Abhur induk hukum praktis mazhab Hanafi."
  },
  {
    "name": "Imdad al-Fattah",
    "author": "Hasan al-Shurunbulali",
    "desc": "Syarah luas atas kitab Nur al-Idah memuat dalil fiqih ibadah Hanafi."
  },
  {
    "name": "Hasyiyah al-Tahtawi 'ala Maraqi al-Falah",
    "author": "Ahmad al-Tahtawi",
    "desc": "Catatan pinggir populer penyempurna fiqih ibadah mazhab Hanafi."
  },
  {
    "name": "Jami' al-Rumuz",
    "author": "Shams al-Din al-Quhistani",
    "desc": "Syarah fiqih Hanafi atas kitab al-Nuqayah yang padat makna."
  },
  {
    "name": "Fatawa Qadi Khan",
    "author": "Al-Hasan bin Mansur al-Ozkandi",
    "desc": "Kumpulan fatwa mu'tamad dan paling otentik dalam mazhab Hanafi."
  },
  {
    "name": "Al-Fatawa al-Bazzaziyyah",
    "author": "Ibn al-Bazzaz al-Kardari",
    "desc": "Koleksi fatwa fiqih Hana

